pub(super) fn api_album_id(album: &crate::library::Album) -> String {
    if let Some(id) = album.id {
        return format!("id:{id}");
    }
    if let Some(uuid) = album.uuid.as_deref()
        && is_safe_media_id(uuid)
    {
        return format!("uuid:{uuid}");
    }
    let mut hasher = Sha256::new();
    hasher.update(album.title.as_bytes());
    hasher.update([0]);
    hasher.update(album.artist().as_bytes());
    hasher.update([0]);
    hasher.update(album.edition.as_deref().unwrap_or_default().as_bytes());
    hasher.update([0]);
    if let Some(first_path) = album
        .tracks
        .first()
        .map(|track| track.path.to_string_lossy())
    {
        hasher.update(first_path.as_bytes());
    }
    let digest = hasher.finalize();
    format!("hash:{}", hex_prefix(&digest, 24))
}

pub(super) fn api_track_id(
    track: &crate::library::Track,
    album: &crate::library::Album,
    index: usize,
) -> String {
    if let Some(uuid) = track.uuid.as_deref()
        && is_safe_media_id(uuid)
    {
        return format!("uuid:{uuid}");
    }
    media_track_id(track, album, index)
}

pub(super) fn api_json_response(status: u16, body: Value) -> Vec<u8> {
    let body = serde_json::to_vec(&body).unwrap_or_else(|_| b"{\"error\":\"json\"}".to_vec());
    let headers = format!(
        "HTTP/1.1 {} {}\r\nContent-Type: application/json\r\nContent-Length: {}\r\nCache-Control: no-store\r\nConnection: close\r\n\r\n",
        status,
        api_status_text(status),
        body.len()
    );
    let mut response = headers.into_bytes();
    response.extend_from_slice(&body);
    response
}

pub(super) fn api_binary_response(status: u16, content_type: &str, body: &[u8]) -> Vec<u8> {
    let headers = format!(
        "HTTP/1.1 {} {}\r\nContent-Type: {}\r\nContent-Length: {}\r\nCache-Control: no-store\r\nConnection: close\r\n\r\n",
        status,
        api_status_text(status),
        content_type,
        body.len()
    );
    let mut response = headers.into_bytes();
    response.extend_from_slice(body);
    response
}

pub(super) fn api_error_response(status: u16, error: &str) -> Vec<u8> {
    api_json_response(status, json!({ "ok": false, "error": error }))
}

pub(super) fn api_response_status(response: &[u8]) -> Option<u16> {
    let header = std::str::from_utf8(response.get(..response.len().min(32))?).ok()?;
    let mut parts = header.split_whitespace();
    match (parts.next(), parts.next()) {
        (Some(version), Some(status)) if version.starts_with("HTTP/") => status.parse().ok(),
        _ => None,
    }
}

pub(super) fn api_status_text(status: u16) -> &'static str {
    match status {
        200 => "OK",
        400 => "Bad Request",
        401 => "Unauthorized",
        404 => "Not Found",
        405 => "Method Not Allowed",
        416 => "Range Not Satisfiable",
        500 => "Internal Server Error",
        _ => "Error",
    }
}

pub(super) fn api_auth_valid(headers: &[(String, String)], auth_token: &str) -> bool {
    let Some(value) = api_header(headers, "authorization") else {
        return false;
    };
    value.trim() == format!("Bearer {auth_token}")
}

pub(super) fn api_media_auth_valid(request: &ApiRequest, auth_token: &str) -> bool {
    api_auth_valid(&request.headers, auth_token)
        || api_query_param(&request.path, "token").is_some_and(|token| token == auth_token)
}

pub(super) fn api_query_param(path: &str, name: &str) -> Option<String> {
    let (_, query) = path.split_once('?')?;
    url::form_urlencoded::parse(query.as_bytes())
        .find(|(key, _)| key == name)
        .map(|(_, value)| value.into_owned())
}

pub(super) fn api_header<'a>(headers: &'a [(String, String)], name: &str) -> Option<&'a str> {
    headers
        .iter()
        .find(|(header, _)| header == name)
        .map(|(_, value)| value.as_str())
}

pub(super) fn api_content_length_from_headers(header_bytes: &[u8]) -> Result<usize, String> {
    let header_text = std::str::from_utf8(header_bytes)
        .map_err(|_| "request headers are not valid UTF-8".to_string())?;
    let headers: Vec<_> = header_text
        .split("\r\n")
        .skip(1)
        .filter_map(|line| {
            let (name, value) = line.split_once(':')?;
            Some((name.trim().to_ascii_lowercase(), value.trim().to_string()))
        })
        .collect();
    api_content_length(&headers)
}

pub(super) fn api_content_length(headers: &[(String, String)]) -> Result<usize, String> {
    match api_header(headers, "content-length") {
        Some(value) => value
            .parse::<usize>()
            .map_err(|_| "invalid Content-Length".to_string()),
        None => Ok(0),
    }
}
